import {ENCYCLOPEDIA,GLOSSARY,ENCYCLOPEDIA_NARRATION} from './encyclopedia-content.js';
import {ENCYCLOPEDIA_MEDIA} from './encyclopedia-media.js';
import {createStatueViewer,createSpecimenViewer} from './statue-viewer.js';
import {createMuseumImageViewer} from './museum-image-viewer.js';
import {createMuseumExhibit} from './museum-exhibits.js';
import {discoveryIllustration} from './discovery-illustrations.js';
import {STATUE_FACTS,MINI_GAMES} from './mini-content.js';

const el=(tag,cls,text)=>{const n=document.createElement(tag);if(cls)n.className=cls;if(text!==undefined)n.textContent=text;return n;};
const SAVE='stjornufar.safn.v1';
export function readMuseumProgress(storage){try{const p=JSON.parse((storage||globalThis.localStorage).getItem(SAVE));return {visited:Array.isArray(p?.visited)?p.visited.filter(id=>ENCYCLOPEDIA.some(e=>e.id===id)):[],last:ENCYCLOPEDIA.some(e=>e.id===p?.last)?p.last:null};}catch{return {visited:[],last:null};}}
export function mediaFor(entry){const extra=ENCYCLOPEDIA_MEDIA[entry.id]||[];if(extra.some(m=>m.type==='image'))return extra;const f=STATUE_FACTS[entry.id];return f?[{type:'image',src:f.image,alt:f.imageAlt,caption:f.imageAlt,credit:f.credit},...extra]:extra;}
export function searchEntries(query='',group='all'){const q=query.trim().toLocaleLowerCase('is');return ENCYCLOPEDIA.filter(e=>(group==='all'||e.group===group)&&[e.name,e.scientificName,e.englishName,e.id==='triceratops'?'Mosi':''].filter(Boolean).join(' ').toLocaleLowerCase('is').includes(q));}

export function createEncyclopedia(host,{getState=()=>({}),audio,onClose,onPlay,onStatue}={}){
 let disposed=false,page='home',current=null,tab='look',selectedTopic=0,viewer=null,exhibit=null,lightbox=null,overlay=null,expanded=null,epoch=0,voice=0;
 let group='all',query='',progress=readMuseumProgress(),body,main,heading,backButton,playingButton=null;
 const initialFocus=document.activeElement;let releaseIsolation=null;
 host.className='museum-root';
 function stopVoice(){voice++;audio?.stopNarration();if(playingButton){playingButton.textContent='▷ Hlusta';playingButton.setAttribute('aria-pressed','false');playingButton=null;}}
 function button(text,fn,cls='museum-button'){const b=el('button',cls,text);b.type='button';b.addEventListener('click',()=>{audio?.effect('tap');fn(b);});return b;}
 function destroyView(){epoch++;stopVoice();releaseIsolation?.();releaseIsolation=null;lightbox?.dispose();lightbox=null;overlay?.remove();overlay=null;viewer?.dispose();viewer=null;exhibit?.dispose();exhibit=null;expanded=null;}
 function shell(title,subtitle,back){destroyView();host.replaceChildren();const header=el('header','museum-header');backButton=button(back?'← Safnið':'← Ævintýrið',back||onClose,'museum-back');const brand=el('div','museum-brand');brand.append(el('span','museum-eyebrow','MOSI & EGILL · NÁTTÚRUSAFNIÐ'));heading=el('h1','',title);heading.tabIndex=-1;brand.append(heading);header.append(backButton,brand);if(back)header.append(button('Aftur í ævintýrið',onClose,'museum-exit'));host.append(header);body=el('div','museum-body');if(subtitle)body.append(el('p','museum-subtitle',subtitle));host.append(body);return body;}
 function announce(text){const live=host.querySelector('.museum-live');if(live)live.textContent=text;}
 function liveRegion(){const n=el('p','museum-live');n.setAttribute('aria-live','polite');return n;}
 function listen(id,text){const b=button('▷ Hlusta',async()=>{if(playingButton===b){stopVoice();return;}stopVoice();audio?.unlock();const token=++voice;playingButton=b;b.textContent='■ Stöðva';b.setAttribute('aria-pressed','true');const ok=await audio?.narrate(id,ENCYCLOPEDIA_NARRATION[id]||text);if(disposed||voice!==token)return;playingButton=null;b.textContent='▷ Hlusta';b.setAttribute('aria-pressed','false');if(!ok&&!audio?.isMuted?.())announce('Upplestur náði ekki að spilast. Textinn er hér til að lesa.');},'museum-button museum-listen');b.setAttribute('aria-pressed','false');return b;}
 function art(entry,cls='museum-card-art'){const wrap=el('div',cls),image=mediaFor(entry).find(m=>m.type==='image');if(image){const img=el('img');let fallback=false;img.addEventListener('error',()=>{if(disposed)return;const core=STATUE_FACTS[entry.id]?.image;if(core&&!fallback&&core!==(image.thumb||image.src)){fallback=true;img.src=core;return;}const local=el('div','museum-offline-art');local.innerHTML=discoveryIllustration(entry.illustration||'fossil');local.setAttribute('aria-label','Teikning úr leiknum');img.replaceWith(local);});img.src=image.thumb||image.src;img.alt='';img.loading='lazy';img.decoding='async';wrap.append(img);}else{wrap.innerHTML=discoveryIllustration(entry.illustration||'fossil');}return wrap;}
 function badge(entry){return entry.group==='small'?'Lítill nágranni':entry.id==='pteranodon'?'Flugeðla':'Risaeðla';}
 function home(){page='home';current=null;const b=shell('Safn Egils',null,null),hero=el('section','museum-welcome');
  const copy=el('div');copy.append(el('span','museum-eyebrow','OPNAÐU DYR AÐ FORTÍÐINNI'),el('h2','','Stórar spurningar.\nÓtrúleg dýr.'),el('p','','Komdu að rannsaka, Egill! Snúðu dýrunum, skoðaðu steingervinga og finndu sögurnar á bak við beinin.'));
  const resume=ENCYCLOPEDIA.find(e=>e.id===progress.last);if(resume)copy.append(button('Halda áfram: '+resume.name,()=>entryPage(resume.id)));
  const seal=el('div','museum-welcome-seal');seal.innerHTML='<svg viewBox="0 0 180 180" aria-hidden="true"><circle cx="90" cy="90" r="78" fill="none" stroke="currentColor" stroke-width="1" stroke-dasharray="2 7"/><path d="M37 124 54 81 80 61 114 61 137 83 141 115 117 136 65 139Z" fill="none" stroke="currentColor" stroke-width="5"/><path d="M94 104c-11 4-19-8-13-17 9-13 29-3 25 13-6 25-38 30-52 8-17-31 15-63 46-47 34 17 29 65-6 77" fill="none" stroke="currentColor" stroke-width="6" stroke-linecap="round"/></svg>';seal.append(el('span','','Safn landkönnuðarins'));hero.append(copy,seal);b.append(hero);
  const rooms=el('nav','museum-rooms');rooms.setAttribute('aria-label','Rannsóknarsalir');for(const[k,title,small,glyph]of[['scale','Stærðarsalurinn','Hversu stór var hún?','↔'],['timeline','Tímavélin','Hver lifði hvenær?','◷'],['lab','Rannsóknarborðið','Hvað segja beinin?','⌕']]){const btn=button('',()=>showExhibit(k),'museum-room');btn.append(el('span','museum-room-icon',glyph),el('strong','',title),el('small','',small));rooms.append(btn);}b.append(rooms);
  const bar=el('div','museum-index-bar');bar.append(el('h2','','Dýrin í safninu'));const state=getState(),wins=Object.values(state.games||{}).filter(v=>v.wins).length;bar.append(el('span','museum-counter',`${ENCYCLOPEDIA.length} dýr · ${wins} af 6 verðlaunastyttum`));b.append(bar);
  const tools=el('div','museum-filters'),search=el('input','museum-search');search.type='search';search.placeholder='Finna dýr eða nafn…';search.setAttribute('aria-label','Leita að dýri');search.value=query;
  const filters=[];for(const[id,label]of[['all','Öll dýr'],['prehistoric','Risarnir'],['small','Litlu nágrannarnir']]){const f=button(label,()=>{group=id;filters.forEach(([key,node])=>node.setAttribute('aria-pressed',String(key===id)));renderGrid();},'museum-filter');f.setAttribute('aria-pressed',String(group===id));filters.push([id,f]);tools.append(f);}tools.append(search);b.append(tools);
  const grid=el('div','museum-grid');b.append(grid);search.addEventListener('input',()=>{query=search.value;renderGrid();});
  function renderGrid(){grid.replaceChildren();for(const e of searchEntries(query,group)){const tile=button('',()=>entryPage(e.id),'museum-animal-card');tile.dataset.animal=e.id;const image=art(e);image.append(el('span','museum-category',badge(e)));if(state.games?.[e.id]?.wins)image.append(el('span','museum-earned','★ Stytta unnin'));const words=el('div','museum-card-copy');words.append(el('strong','',e.id==='triceratops'?'Mosi · '+e.name:e.name),el('small','',e.scientificName||e.englishName||''),el('span','museum-card-link',progress.visited.includes(e.id)?'Skoða aftur ↗':'Opna og uppgötva ↗'));tile.append(image,words);grid.append(tile);}if(!grid.childElementCount)grid.append(el('p','','Ekkert dýr fannst með þessu nafni. Prófaðu annað nafn.'));}
  renderGrid();const footer=el('div','museum-footnote');footer.append(el('p','','Öll fræðslan er opin. Styttur vinnast í leikjunum. Hér má skoða aftur og aftur.'),button('Orðasafnið',glossary,'museum-text-button'));b.append(footer);b.scrollTop=0;
 }
 function entryPage(id,newTab='look'){const entry=ENCYCLOPEDIA.find(e=>e.id===id);if(!entry)return;current=entry;page='entry';tab=newTab;selectedTopic=0;if(!progress.visited.includes(id))progress.visited.push(id);progress.last=id;try{localStorage.setItem(SAVE,JSON.stringify(progress));}catch{}
  const b=shell(entry.id==='triceratops'?'Mosi · '+entry.name:entry.name,null,home);const identity=el('div','museum-identity');identity.append(el('span','museum-tag',badge(entry)),el('span','',entry.scientificName||''));if(entry.englishName&&entry.englishName!==entry.scientificName)identity.append(el('span','',`Enska: ${entry.englishName}`));b.append(identity);
  const tabs=el('nav','museum-tabs');tabs.setAttribute('aria-label','Skoðunarleiðir');const tabButtons=[];for(const[id,label]of[['look','Skoða'],['read','Lesa og hlusta'],['investigate','Rannsaka']]){const t=button(label,()=>{tab=id;renderTab();},'museum-tab');tabButtons.push([id,t]);tabs.append(t);}b.append(tabs);main=el('div','museum-entry-main');b.append(main,liveRegion());
  function renderTab(){destroyView();main.replaceChildren();tabButtons.forEach(([id,node])=>node.setAttribute('aria-pressed',String(tab===id)));if(tab==='look')look(entry);else if(tab==='read')read(entry);else investigate(entry);}
  renderTab();b.scrollTop=0;heading.focus({preventScroll:true});
 }
 function metaLine(entry){const m=el('div','museum-meta');if(entry.time)m.append(el('span','',entry.time.label));if(entry.size)m.append(el('span','',entry.size.label));return m;}
 function look(entry){const layout=el('div','museum-look'),visual=el('section','museum-visual'),modelHost=el('div','museum-model'),copy=el('section','museum-intro');
  copy.append(el('span','museum-eyebrow','KYNNTU ÞÉR DÝRIÐ'),el('h2','','Komum nær!'),el('p','',entry.intro),metaLine(entry));copy.append(listen(entry.introNarration||`encyclopedia_${entry.id}_intro`,entry.intro));
  if(entry.group==='prehistoric'){visual.append(modelHost);viewer=createStatueViewer(modelHost,{species:entry.id,hotspots:entry.hotspots||[],onExpand:()=>expandModel(modelHost)});visual.append(el('p','museum-model-note','Ævintýramódel · Litirnir eru ímyndaðir. Dragðu til að snúa. Klíptu með tveimur fingrum til að stækka.'));const points=el('div','museum-hotspots'),pointText=el('p','museum-hotspot-copy');for(const[h,p]of(entry.hotspots||[]).entries()){points.append(button(p.label,()=>{viewer?.focusHotspot?.(h);pointText.textContent=p.text;},'museum-chip'));}visual.append(points,pointText);
  }else{visual.append(art(entry,'museum-nature-image'));visual.append(el('p','museum-model-note','Nágranni úr náttúrunni · Myndin sýnir dæmi úr þessum dýrahópi.'));}
  const state=getState();if(MINI_GAMES[entry.id]){const box=el('div','museum-game-link');box.append(el('strong','',state.games?.[entry.id]?.wins?'★ Þessi stytta er í safninu þínu':'Viltu vinna styttu af þessu dýri?'));if(state.found?.includes(entry.id)){box.append(button('Spila leikinn',()=>onPlay?.(entry.id)));if(state.games?.[entry.id]?.wins)box.append(button('Verðlaunastyttan mín',()=>onStatue?.(entry.id),'museum-text-button'));}else box.append(el('p','','Hittu dýrið í ævintýrinu og smelltu á það til að spila. Fræðslan er alltaf opin hér.'));copy.append(box);}
  layout.append(visual,copy);main.append(layout);gallery(entry);
 }
 function gallery(entry){const all=mediaFor(entry),images=all.filter(m=>m.type==='image'),models=all.filter(m=>m.type==='model');if(!all.length)return;const h=el('div','museum-index-bar');h.append(el('h2','','Á rannsóknarborðinu'),el('span','museum-counter','Snertu mynd til að stækka'));main.append(h);const grid=el('div','museum-gallery');
  images.forEach((m,i)=>{const b=button('',()=>openPhotos(images,i),'museum-photo-card'),img=el('img');img.addEventListener('error',()=>{if(!disposed)img.replaceWith(el('span','museum-missing-photo','Myndin bíður. Prófaðu með netsambandi.'));},{once:true});img.src=m.thumb||m.src;img.alt=m.alt||entry.name;img.loading='lazy';img.decoding='async';b.append(img,el('strong','',m.caption||m.alt||entry.name),el('span','','⊕ Stækka mynd'));grid.append(b);});
  models.forEach(m=>{const b=button('',()=>openSpecimen(m),'museum-photo-card museum-specimen-card');b.append(el('span','museum-specimen-symbol','◈'),el('strong','',m.caption||m.alt||'Þrívíður steingervingur'),el('span','','Snúa safngripnum í 3D'));grid.append(b);});main.append(grid);
 }
 function blockUnderlay(value){for(const child of host.children)if(child!==overlay)child.inert=value;}
 function closePhoto(){lightbox?.dispose();lightbox=null;overlay?.remove();overlay=null;blockUnderlay(false);viewer?.setPaused(false);host.querySelector('.museum-photo-card')?.focus?.({preventScroll:true});}
 function openPhotos(images,index){stopVoice();viewer?.setPaused(true);overlay=el('section','museum-overlay');host.append(overlay);blockUnderlay(true);lightbox=createMuseumImageViewer(overlay,{images,index,onClose:closePhoto});overlay.querySelector('button')?.focus?.();}
 function isolate(node){releaseIsolation?.();const changed=[];while(node&&node!==host){for(const sibling of node.parentElement?.children||[])if(sibling!==node){changed.push([sibling,sibling.inert]);sibling.inert=true;}node=node.parentElement;}releaseIsolation=()=>{for(const[n,previous]of changed)n.inert=previous;};}
 function expandModel(modelHost){if(expanded)return;expanded={node:modelHost,focus:document.activeElement};isolate(modelHost);modelHost.classList.add('museum-expanded');const b=button('← Til baka í safnið',collapseModel,'museum-expand-back');modelHost.append(b);expanded.button=b;b.focus();}
 function collapseModel(){if(!expanded)return;expanded.node.classList.remove('museum-expanded');expanded.button.remove();expanded.focus?.focus?.({preventScroll:true});expanded=null;releaseIsolation?.();releaseIsolation=null;}
 function openSpecimen(m){stopVoice();viewer?.dispose();viewer=null;const oldFocus=document.activeElement;overlay=el('section','museum-overlay museum-specimen-overlay');const top=el('header','museum-specimen-heading');top.append(button('← Til baka',()=>{viewer?.dispose();viewer=null;overlay?.remove();overlay=null;entryPage(current.id);oldFocus?.focus?.();},'museum-back'),el('h2','',m.alt||'Safngripur í þrívídd'));const surface=el('div','museum-specimen-surface');overlay.append(top,surface,el('p','museum-specimen-credit',(m.caption||'')+' · '+m.credit+' · '+m.license));host.append(overlay);isolate(overlay);overlay.querySelector('button')?.focus?.();viewer=createSpecimenViewer(surface,{src:m.src,label:m.alt||m.caption,credit:m.credit});}
 function read(entry){const grid=el('div','museum-reading'),menu=el('nav','museum-topic-menu');menu.setAttribute('aria-label','Fræðslukaflar');const article=el('article','museum-article'),buttons=[];entry.topics.forEach((t,i)=>{const b=button('',()=>{selectedTopic=i;topic(true);},'museum-topic');b.append(el('span','',String(i+1).padStart(2,'0')),el('strong','',t.title));buttons.push(b);menu.append(b);});menu.append(button('Orðasafn',()=>glossary(()=>entryPage(entry.id,'read')),'museum-text-button'));grid.append(menu,article);main.append(grid);
  function topic(scroll=false){stopVoice();const t=entry.topics[selectedTopic];if(!t)return;buttons.forEach((b,i)=>b.setAttribute('aria-pressed',String(i===selectedTopic)));article.replaceChildren();article.append(el('span','museum-eyebrow',`KAFLI ${selectedTopic+1} AF ${entry.topics.length}`),el('h2','',t.title),el('p','museum-lede',t.summary));for(const p of(t.paragraphs||[]))article.append(glossaryParagraph(p,article));const certainty={evidence:'Þetta styðja gögnin',inferred:'Túlkun vísindamanna',debated:'Enn ráðgáta'};if(t.certainty)article.append(el('p','museum-evidence',certainty[t.certainty]||t.certainty));const text=[t.title,t.summary,...(t.paragraphs||[])].join(' ');article.append(listen(t.narration||`encyclopedia_${entry.id}_${t.id}`,text));sources(article,t.sources||entry.sources);const nav=el('div','museum-reading-next');if(selectedTopic>0)nav.append(button('← Fyrri kafli',()=>{selectedTopic--;topic(true);},'museum-button secondary'));if(selectedTopic<entry.topics.length-1)nav.append(button('Næsti kafli →',()=>{selectedTopic++;topic(true);}));article.append(nav);if(scroll)article.scrollIntoView?.({block:'start',behavior:'instant'});}
  topic();
 }
 function glossaryParagraph(text,article){
  const p=el('p');const terms=GLOSSARY.filter(t=>t.term&&text.toLocaleLowerCase('is').includes(t.term.toLocaleLowerCase('is')));if(!terms.length){p.textContent=text;return p;}
  const names=terms.map(t=>t.term.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).sort((a,b)=>b.length-a.length);const pattern=new RegExp('('+names.join('|')+')','giu');let cursor=0;
  for(const match of text.matchAll(pattern)){if(/[\p{L}]/u.test(text[match.index-1]||'')||/[\p{L}]/u.test(text[match.index+match[0].length]||''))continue;p.append(document.createTextNode(text.slice(cursor,match.index)));const item=terms.find(t=>t.term.toLocaleLowerCase('is')===match[0].toLocaleLowerCase('is'));const word=button(match[0],()=>{let note=article.querySelector('.museum-word-note');if(!note){note=el('aside','museum-word-note');note.setAttribute('role','status');p.after(note);}note.replaceChildren(el('strong','',item.term),el('p','',item.definition),button('Skil!',()=>note.remove(),'museum-text-button'));note.scrollIntoView?.({block:'nearest'});},'museum-word');word.setAttribute('aria-label','Hvað merkir '+match[0]+'?');p.append(word);cursor=match.index+match[0].length;}
  p.append(document.createTextNode(text.slice(cursor)));return p;
 }
 function sources(target,values){if(!values?.length)return;const details=el('details','museum-sources');details.append(el('summary','','Heimildir og vísbendingar'));const intro=el('p','','Fræðslan er skrifuð fyrir safnið út frá þessum heimildum. Við höldum áfram að læra þegar nýir steingervingar finnast.');details.append(intro);for(const s of values){const url=typeof s==='string'?s:s.url;const line=el('p','',typeof s==='string'?s:(s.title+' · '+url));details.append(line);}target.append(details);}
 function investigate(entry){const q=entry.question;const panel=el('section','museum-investigation');panel.append(el('span','museum-eyebrow','RANNSÓKN EGILS'),el('h2','','Skoðum vísbendingarnar'));if(!q){panel.append(el('p','','Skoðaðu dýrið og finndu eitt atriði sem kemur þér á óvart.'));main.append(panel);return;}
  panel.append(el('p','museum-lede',q.prompt));const options=el('div','museum-answer-options'),feedback=el('p','museum-feedback');feedback.setAttribute('aria-live','polite');let answered=false;for(const[inx,option]of q.options.entries()){const label=typeof option==='string'?option:option.label;const b=button(label,()=>{if(answered)return;if(inx===q.answer){answered=true;feedback.textContent='Þú fannst vísbendinguna! '+q.explanation;b.classList.add('correct');audio?.effect('fossil');for(const n of options.children)n.disabled=true;panel.append(button('Rannsaka aftur',()=>{main.replaceChildren();investigate(entry);},'museum-button secondary'));}else{feedback.textContent='Skoðum þetta saman. '+q.explanation+' Prófaðu svo aftur.';b.disabled=true;b.classList.add('tried');}},'museum-answer');options.append(b);}panel.append(options,feedback,button('Skoða dýrið aftur',()=>entryPage(entry.id,'look'),'museum-text-button'));main.append(panel);sources(panel,entry.sources);
 }
 function showExhibit(kind){page='exhibit';const names={scale:'Stærðarsalurinn',timeline:'Tímavélin',lab:'Rannsóknarborðið'};const b=shell(names[kind],null,home);const area=el('section','museum-exhibit-host');b.append(area);exhibit=createMuseumExhibit(area,{kind,entries:ENCYCLOPEDIA,audio,onClose:home});}
 function glossary(back=home){page='glossary';const b=shell('Orðasafn Egils','Stór orð verða skemmtileg þegar við vitum hvað þau merkja.',back);const grid=el('div','museum-glossary');for(const item of GLOSSARY){const card=el('article');card.append(el('h2','',item.term),el('p','',item.definition));grid.append(card);}b.append(grid);}
 function handleBack(){if(lightbox){closePhoto();return true;}if(overlay){overlay.remove();overlay=null;entryPage(current.id);return true;}if(expanded){collapseModel();return true;}if(page!=='home'){home();return true;}return false;}
 home();
 return {home,openEntry:entryPage,handleBack,dispose(){if(disposed)return;disposed=true;destroyView();host.replaceChildren();initialFocus?.focus?.({preventScroll:true});}};
}
